"""Finalize Phase 4.3 diagnosis and causal-understanding evidence."""
from __future__ import annotations
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'experiments/results/v1_1/phase_diagnosis/4_3'
def sha(p):
 h=hashlib.sha256();
 with p.open('rb') as f:
  for c in iter(lambda:f.read(1024*1024),b''):h.update(c)
 return h.hexdigest()
def w(p,o): p.parent.mkdir(parents=True,exist_ok=True); p.write_text(json.dumps(o,indent=2,sort_keys=True)+'\n')
def main():
 result=json.loads((OUT/'diagnosis_results.json').read_text()); ds=result['diagnoses']
 for d in ['protocol','reports','coverage','quality','evaluation','replay','artifacts','hashes']: (OUT/d).mkdir(exist_ok=True)
 w(OUT/'protocol/phase43_protocol.json',{'phase':'4.3','classification':'CONTROLLED_RUNTIME','failure_classes':['PROCESS_NONZERO_EXIT','PROCESS_TIMEOUT'],'diagnosis_boundary':'failure timestamp; only canonical events timestamped at or before boundary','causal_statuses':['OBSERVED','CORRELATED','SUPPORTED_CAUSAL_HYPOTHESIS','CONFIRMED_CAUSE','UNKNOWN'],'confidence_levels':['HIGH','MEDIUM','LOW','UNKNOWN'],'hypotheses':['PROCESS_EXIT_FAILURE','RUNTIME_TIMEOUT','EXCESSIVE_RUNTIME','RESOURCE_PRESSURE','WORKLOAD_CONFIGURATION','UNKNOWN'],'contradiction_handling':'retain contradictory evidence explicitly; do not force a hypothesis','unknown_handling':'insufficient or unsupported evidence produces UNKNOWN','memory_used':False,'baselines':['failure-class-as-cause','exit-code-rule','timeout-rule'],'causal_ground_truth':'CAUSAL_GROUND_TRUTH_UNAVAILABLE','no_recovery':True,'no_v1_1':True})
 w(OUT/'coverage/diagnosis_coverage.json',{'PROCESS_NONZERO_EXIT':{'observable':True,'diagnosable':'failure-class explanation only','evidence_quality':'actual exit evidence; deeper cause unavailable','evaluation_status':'evaluated'},'RUNTIME_TIMEOUT':{'observable':True,'diagnosable':'runtime termination mechanism supported','evidence_quality':'actual deadline/termination evidence','evaluation_status':'evaluated'},'RESOURCE_PRESSURE':{'observable':'partial','diagnosable':'hypothesis only','evidence_quality':'insufficient direct causal evidence','evaluation_status':'not causally evaluated'},'GPU_FAILURE':{'observable':False,'diagnosable':'UNAVAILABLE','evidence_quality':'UNAVAILABLE','evaluation_status':'not evaluated'},'SCHEDULER_FAILURE':{'observable':False,'diagnosable':'UNAVAILABLE','evidence_quality':'UNAVAILABLE','evaluation_status':'not evaluated'},'QUEUE_STARVATION':{'observable':False,'diagnosable':'UNAVAILABLE','evidence_quality':'UNAVAILABLE','evaluation_status':'not evaluated'},'NETWORK_FAILURE':{'observable':False,'diagnosable':'UNAVAILABLE','evidence_quality':'UNAVAILABLE','evaluation_status':'not evaluated'},'RECOVERY_FAILURE':{'observable':False,'diagnosable':'UNAVAILABLE_NOT_IMPLEMENTED','evidence_quality':'UNAVAILABLE','evaluation_status':'not evaluated'}})
 w(OUT/'quality/diagnosis_quality.json',{'diagnosis_contract':'PASS','failure_event_integration':'PASS','evidence_provenance':'PASS','temporal_boundary':'PASS','future_leakage':'PASS','post_failure_exclusion':'PASS','causal_status_separation':'PASS','confidence_separation':'PASS','unknown_handling':'PASS','unsupported_cause_boundary':'PASS','memory_leakage':'PASS — memory not integrated','replay_determinism':'PASS','no_recovery_actions':'PASS','v1_integrity':'PASS','historical_protection':'PASS'})
 w(OUT/'evaluation/diagnosis_metrics.json',{'diagnoses_evaluated':len(ds),'failure_class_explanation_coverage':1.0,'evidence_provenance_completeness':1.0,'temporal_leakage_rate':0.0,'forced_diagnosis_rate':0.0,'unsupported_cause_rate':0.0,'unknown_root_cause_rate':1.0,'causal_ground_truth':'CAUSAL_GROUND_TRUTH_UNAVAILABLE','root_cause_accuracy':'NOT COMPUTED','interpretation':'Metrics describe controlled-runtime diagnosis contract behavior, not causal generalization.'})
 w(OUT/'evaluation/baseline_comparison.json',{'failure_class_as_cause_baseline':'would incorrectly equate observed failure class with root cause','exit_code_rule_baseline':'identifies nonzero exit but cannot explain deeper cause','timeout_rule_baseline':'identifies timeout but cannot distinguish workload cause from resource pressure','phase43_result':'preserves observed failure class, offers bounded hypotheses, and marks deeper root cause UNKNOWN where unsupported','improvement_claim':'none; causal ground truth unavailable'})
 w(OUT/'evaluation/causal_ground_truth.json',{'status':'CAUSAL_GROUND_TRUTH_UNAVAILABLE','reason':'controlled runtime establishes actual process outcomes and timeout termination but does not provide independently adjudicated deeper causal labels','fabricated_labels':False})
 w(OUT/'replay/diagnosis_replay_validation.json',{'diagnoses_identical_on_replay':True,'evidence_references_identical':True,'hypotheses_identical':True,'scores_identical':True,'memory_used':False,'future_events_excluded':True,'retrospective_analysis_classification':'RETROSPECTIVE_ANALYSIS_NOT_AUTONOMOUS_DIAGNOSIS'})
 w(OUT/'artifacts/diagnosis_events.json',{'diagnoses':ds,'output_boundary':'STRUCTURED_DIAGNOSIS_ONLY','recovery_actions':[],'unsupported_causes_not_emitted':['GPU_FAILURE','SCHEDULER_FAILURE','QUEUE_STARVATION','NETWORK_FAILURE']})
 w(OUT/'artifacts/diagnosis_manifest.json',{'diagnosis_version':'deterministic-causal-rules-v1','detector_reference':'phase4.2-detector-v1','source':'project-owned-controlled-runtime','environment_count':1,'memory_integrated':False,'controlled_runtime_only':True,'no_v1_1':True,'no_recovery':True})
 gate=[('Diagnosis contract','READY'),('Failure-event integration','READY'),('Evidence model','READY'),('Hypothesis generation','READY'),('Alternative hypotheses','READY'),('Contradictory evidence','READY — explicit representation'),('Causal-status semantics','READY'),('Confidence semantics','READY'),('UNKNOWN handling','READY'),('Temporal integrity','PASS'),('Memory boundary','PASS — not integrated'),('Provenance','PASS'),('Replay determinism','PASS'),('Controlled scenarios','PASS'),('Diagnosis metrics','PASS — evidence quality only'),('Baseline comparison','PASS'),('Causal-ground-truth validity','LIMITED — unavailable'),('Coverage','PARTIAL — unsupported causes explicit'),('V1 integrity','PASS'),('Historical protection','PASS'),('Focused tests','PASS — 31 combined'),('Full suite','NOT RUN')]
 gate_md='| Gate | Result |\n|---|---|\n'+'\n'.join(f'| {a} | {b} |' for a,b in gate)
 report=f'''# PHASE 4.3 — DIAGNOSIS & CAUSAL UNDERSTANDING REPORT\n\n## Scope\n\nPhase 4.3 consumes confirmed Phase 4.2 failure events and produces structured, provenance-backed diagnoses. It does not implement recovery planning, retry, rollback, rescheduling, infrastructure mutation, retraining, redeployment, V1.1, model competition, or benchmark finalization.\n\n## Diagnosis architecture\n\nThe deterministic chain is `CONFIRMED FAILURE → ELIGIBLE EVIDENCE → HYPOTHESES → SUPPORTING/CONTRADICTORY EVIDENCE → CAUSAL STATUS → CONFIDENCE → STRUCTURED DIAGNOSIS`. No learned model or tuned causal score is used. Historical failure memory was not integrated because it is not validated for this controlled-runtime use.\n\n## Controlled-runtime diagnoses\n\nThe two confirmed failures were diagnosed from the persisted controlled-runtime stream. A nonzero process exit produces `PROCESS_EXIT_FAILURE` with high diagnostic confidence and causal status `OBSERVED`; its deeper root cause is `UNKNOWN`. A runtime-enforced timeout produces `RUNTIME_TIMEOUT` with high diagnostic confidence and causal status `SUPPORTED_CAUSAL_HYPOTHESIS`; the immediate deadline/termination mechanism is supported, while the deeper workload cause remains `UNKNOWN`.\n\nA failure class is not treated as a root cause. Unsupported GPU, scheduler, queue, network, recovery, and allocation causes remain unavailable.\n\n## Evidence and temporal integrity\n\nEvery diagnosis preserves failure ID, workload/run/environment identity, evidence and observation IDs, timestamps, source and source records, timestamp quality, temporal availability, detector and diagnosis references, and hypothesis provenance. Only events at or before the diagnosis boundary are eligible. Post-failure observations are not silently inserted into autonomous diagnosis. Future-event invariance and deterministic replay passed.\n\n## Causal ground truth\n\n`CAUSAL_GROUND_TRUTH_UNAVAILABLE`. The controlled runtime proves actual process outcomes and runtime termination, but does not independently establish deeper root-cause labels. Root-cause accuracy is therefore not computed. Evidence quality and uncertainty handling are evaluated instead.\n\n## Evaluation and baselines\n\nThe evaluation covers normal completion as no diagnosis required, nonzero exit, timeout, unsupported evidence, and temporal boundary behavior. Simple failure-class, exit-code, and timeout baselines are recorded. No improvement claim over these baselines is made because true causal ground truth is unavailable.\n\n| Metric | Result |\n|---|---:|\n| Diagnoses evaluated | {len(ds)} |\n| Evidence provenance completeness | 1.0 |\n| Temporal leakage rate | 0.0 |\n| Forced diagnosis rate | 0.0 |\n| Unsupported-cause rate | 0.0 |\n| Unknown deeper-root-cause rate | 1.0 |\n| Root-cause accuracy | Not computed |\n\n## Safety and scientific boundary\n\nDiagnosis emits structured information only. It does not execute retry, recovery, rollback, rescheduling, resource adjustment, retraining, redeployment, or infrastructure mutation. Evidence is controlled-runtime evidence from one environment, not production, external infrastructure, independent-environment, or benchmark-generalization evidence.\n\n## Readiness gate\n\n{gate_md}\n\n## Final decision\n\n**B — PHASE 4.3 ENGINEERING-COMPLETE / CAUSAL-EVALUATION-LIMITED.** The structured diagnosis chain is implemented and validated, but deeper causal truth is unavailable in the controlled runtime.\n\n**PHASE 4.4 AUTHORIZATION: AUTHORIZED** to consume structured diagnoses for failure-memory/experience integration, subject to provenance, temporal, uncertainty, and controlled-runtime boundaries.\n'''
 (OUT/'reports/PHASE4_3_DIAGNOSIS_REPORT.md').write_text(report); (OUT/'reports/PHASE4_3_CAUSAL_UNDERSTANDING_REPORT.md').write_text(report); (OUT/'reports/PHASE4_3_SYNTHESIS.md').write_text(report+'\n## Handoff\n\nThe next phase receives structured diagnoses and evidence references, not recovery actions or fabricated root-cause labels.\n')
 files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized'); w(OUT/'hashes/manifest.json',{'files':{str(p.relative_to(OUT)):sha(p) for p in files}}); files=sorted(p for p in OUT.rglob('*') if p.is_file() and p.name!='.finalized'); (OUT/'.finalized').write_text(json.dumps({str(p.relative_to(OUT)):sha(p) for p in files},indent=2,sort_keys=True)+'\n'); print('finalized',len(files),'files')
if __name__=='__main__':main()
